"""Original thyroid chapter: function tests, hypothyroidism and pregnancy."""
from qbank_authoring import question,ref,finalize
NI=ref('NICE NG145: Thyroid Disease Assessment and Management','https://www.nice.org.uk/guidance/NG145/chapter/recommendations')
HT=ref('ATA: Treatment of Hypothyroidism Guideline, 2014','https://doi.org/10.1089/thy.2014.0028')
PG=ref('ATA: Thyroid Disease in Preconception, Pregnancy and Postpartum, 2026','https://journals.sagepub.com/doi/pdf/10.1177/10507256261445624')
TH=ref('ATA: Hyperthyroidism and Other Causes of Thyrotoxicosis, 2016','https://journals.sagepub.com/doi/epdf/10.1089/thy.2016.0229')
MC=ref('Joint Consensus: Management of Myxoedema Coma, 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13452032/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Fatigue, cold intolerance and constipation accompany TSH 28 mIU/L and low free T4. Which pattern is present?', 'Overt primary hypothyroidism',[
 ('Subclinical hypothyroidism','Free T4 is low rather than normal.'),('Central hypothyroidism as the best fit','The markedly elevated TSH indicates primary thyroid failure in this context.'),('Isolated euthyroid hyperthyroxinemia','Free T4 is reduced and symptoms fit deficiency.')],
 'Interpret TSH with the target hormone', '**Primary gland failure lowers thyroid hormone and raises pituitary TSH drive.**',['Autoimmune disease is a common cause in iodine-sufficient settings.','Treatment and cause assessment should be tailored to the patient.'], '**Use levothyroxine as standard replacement.**',['Age and cardiac risk determine the starting strategy.','Do not confuse overt disease with an isolated mild TSH rise.'],[['TSH','High'],['Free T4','Low'],['Classification','Overt primary hypothyroidism']],[NI,HT],'clinical_scenario')
q('A nonpregnant adult has normal free T4 and TSH 12–14 mIU/L on two samples three months apart. Which approach is supported by NICE guidance?', 'Consider levothyroxine for persistent subclinical hypothyroidism',[
 ('Normal free T4 means no thyroid abnormality exists','The elevated TSH defines a subclinical pattern.'),('Immediate antithyroid medication','That would reduce hormone synthesis further.'),('Every mild isolated TSH rise requires identical lifelong treatment','Persistence, degree, age and context matter.')],
 'Persistence and magnitude affect the treatment decision', '**NICE advises considering treatment when TSH is at least 10 on two occasions three months apart.**',['Lower elevations can be transient and often need observation or a selected symptom trial.','Pregnancy has a separate guideline pathway.'], '**Discuss expected benefit and uncertainty.**',['Review symptoms, antibodies, age and cardiovascular context.','Avoid attributing every nonspecific symptom solely to the biochemical result.'],[['Pattern','High TSH/normal free T4'],['Persistent TSH at least 10','Consider replacement'],['Lower elevation','Individualized observation or trial']],[NI],'clinical_scenario')
q('A clinically euthyroid nonpregnant adult has normal TSH and free T4 but positive TPO antibodies. What is the best general approach?', 'Monitor thyroid function according to risk rather than treating antibodies alone',[
 ('Give levothyroxine solely to normalize the antibody titer','Antibody positivity without dysfunction does not by itself mandate replacement.'),('Use methimazole to suppress autoimmunity','It inhibits hormone synthesis and is not indicated here.'),('The antibodies prove imminent inevitable thyroid failure','They increase risk but do not determine a fixed outcome.')],
 'Autoimmunity and current hormone failure are different findings', '**TPO antibodies support autoimmune susceptibility.**',['Some individuals remain euthyroid for years.','Pregnancy and symptoms change monitoring needs.'], '**Follow function rather than repeated antibody titers.**',['Educate about relevant symptoms.','Reassess promptly if the clinical context changes.'],[['Antibodies','Risk/etiological marker'],['TSH/free T4','Current function'],['Treatment','Based on dysfunction and context']],[NI,HT])
q('How should routine oral levothyroxine be taken to improve consistency of absorption?', 'Consistently on an empty stomach, such as before breakfast or at bedtime well separated from food',[
 ('At a different time with varying meals every day','Variable food exposure can destabilize absorption.'),('Mixed with calcium and iron supplements in the same dose','These can impair absorption.'),('Only on days when fatigue is present','Replacement requires a regular regimen.')],
 'Consistency is as important as the chosen schedule', '**Food and interacting agents can reduce or vary absorption.**',['A bedtime schedule is an alternative when adequately separated from eating.','Formulation changes can warrant reassessment.'], '**Choose a sustainable routine.**',['Review missed doses and interactions before escalating.','Use appropriate timing for follow-up blood tests.'],[['Preferred principle','Consistent fasting administration'],['Interactions','Calcium, iron and other binders'],['Reassessment','After relevant regimen changes']],[HT])
q('TSH rises after a patient starts taking ferrous sulfate together with levothyroxine each morning. What is the best first explanation?', 'Reduced levothyroxine absorption from coadministration',[
 ('Iron necessarily causes a new pituitary tumor','The timing and known interaction give a simpler mechanism.'),('The original thyroid diagnosis must have been wrong','A drug interaction can alter replacement control.'),('All patients require permanent doubling of levothyroxine when iron is started','Separating doses and reassessing may resolve the issue.')],
 'Check administration before diagnosing progressive thyroid failure', '**Iron can bind or interfere with levothyroxine absorption.**',['Calcium has a similar clinically relevant interaction.','A traditional separation is about four hours, following the product and local guidance.'], '**Correct timing and reassess TSH after an appropriate interval.**',['Review other interacting drugs and gastrointestinal disease.','Do not make repeated unobserved dose changes.'],[['New exposure','Iron taken with levothyroxine'],['Mechanism','Reduced absorption'],['Response','Separate and reassess']],[HT],'clinical_scenario')
q('An older patient with coronary disease has overt primary hypothyroidism. Which replacement strategy is generally appropriate?', 'Start with a low levothyroxine dose and titrate cautiously',[
 ('Use a large full replacement load in every stable outpatient','This can provoke ischemia or arrhythmia in susceptible patients.'),('Never treat because coronary disease is present','Treatment remains important but must be cautious.'),('Use antithyroid medication first','The disorder is hormone deficiency.')],
 'The cardiovascular system adapts to the speed of replacement', '**Thyroid hormone increases cardiac workload and oxygen demand.**',['Younger healthy adults can often tolerate a different starting approach.','Symptoms and TSH guide gradual adjustment in primary disease.'], '**Monitor for angina and arrhythmia.**',['Avoid both undertreatment and overshoot.','Severe decompensated hypothyroidism is a separate emergency context.'],[['Stable CAD','Low starting dose'],['Titration','Gradual and monitored'],['Hazard','Ischemia or arrhythmia with rapid excess']],[HT,NI],'clinical_scenario')
q('Why is TSH usually reassessed several weeks rather than a few days after a levothyroxine dose change?', 'The long T4 half-life and feedback response require time to reach a new steady state',[
 ('TSH cannot ever respond to thyroid replacement','It responds but not instantly.'),('Levothyroxine is completely eliminated within one hour','Its half-life is roughly a week in euthyroid physiology.'),('A normal early free T4 guarantees a final normal TSH','The feedback response can lag.')],
 'Avoid chasing a delayed marker with rapid repeated changes', '**A common reassessment interval is about four to six weeks after a dose adjustment.**',['Longstanding marked TSH elevation can take longer to normalize fully.','Symptoms, pregnancy and urgency can alter monitoring needs.'], '**Check adherence and dosing context.**',['Frequent small uncoordinated changes can overshoot.','Primary and central hypothyroidism use different monitoring markers.'],[['T4 half-life','Approximately one week'],['Steady-state assessment','Several weeks'],['TSH','Feedback marker with delay']],[HT,NI])
q('Hypothermia, bradycardia, hypoventilation and altered consciousness occur in severe hypothyroidism after an infection. Which diagnosis is most concerning?', 'Myxoedema coma or decompensated severe hypothyroidism',[
 ('A patient must be fully comatose for this syndrome to exist','Altered mental status can be less than coma.'),('Uncomplicated subclinical hypothyroidism','This is a multisystem emergency.'),('Thyroid storm','That usually has a thyrotoxic rather than deficiency phenotype.')],
 'The name can understate the range of consciousness changes', '**Severe thyroid deficiency can decompensate with infection, cold or sedating drugs.**',['Hyponatremia, hypoglycemia and respiratory failure may coexist.','The TSH need not be high if the cause is central.'], '**Use critical-care support and thyroid hormone replacement.**',['Treat the precipitant.','Provide adrenal coverage while adrenal insufficiency is assessed.'],[['Temperature','Often low'],['Circulation/respiration','Bradycardia and hypoventilation'],['Care','Endocrine and critical-care emergency']],[MC,HT],'clinical_scenario')
q('What is the correct endocrine treatment principle in suspected myxoedema coma?', 'Give glucocorticoid coverage before or alongside urgent thyroid hormone replacement when adrenal status is uncertain',[
 ('Wait for a dynamic adrenal test before any treatment','This can dangerously delay emergency care.'),('Use oral routine outpatient titration alone in every unstable patient','Decompensation requires a monitored emergency approach.'),('Treat only the TSH result and ignore ventilation','Respiratory and cardiovascular support are central.')],
 'Severe thyroid replacement can unmask inadequate adrenal reserve', '**IV levothyroxine is a standard emergency option when available.**',['Selected T3 use depends on severity, cardiac risk and expert guidance.','Loading and ongoing doses are individualized in older or cardiac patients.'], '**Treat the patient’s organ failure as well as hormone deficiency.**',['Support ventilation and circulation.','Use cautious warming and correct metabolic abnormalities under monitoring.'],[['Adrenal safety','Empiric coverage when indicated'],['Thyroid therapy','Urgent monitored replacement'],['Support','Respiratory, circulatory and trigger care']],[MC,HT])
q('A well patient taking high-dose biotin has suppressed TSH and unexpectedly high free T4 on a susceptible assay. What should be considered?', 'Biotin interference mimicking biochemical hyperthyroidism',[
 ('The pattern proves Graves disease regardless of symptoms','Analytical interference must be considered.'),('Biotin causes identical interference on every platform at every dose','The effect depends on assay design, dose and timing.'),('Begin definitive radioiodine before checking the mismatch','This risks treating an artifact.')],
 'Ask about supplements when laboratory and clinical findings disagree', '**Biotin-streptavidin assay systems can produce directionally misleading thyroid results.**',['The apparent pattern can resemble thyrotoxicosis.','Other immunoassays may also be affected.'], '**Coordinate a washout or alternative assay with the laboratory.**',['The appropriate interval depends on dose, renal function and platform.','Do not replace laboratory consultation with one universal washout rule.'],[['Clue','Biochemical-clinical mismatch'],['Exposure','High-dose biotin'],['Response','Laboratory-guided confirmation']],[NI,TH],'clinical_scenario')
q('A critically ill patient has low T3, low-normal free T4 and low-normal TSH without a convincing prior thyroid history. Which interpretation is most likely?', 'Nonthyroidal illness-related changes',[
 ('Primary hypothyroidism is proven despite non-elevated TSH','The pattern can reflect acute systemic illness.'),('Routine T3 normalization is required in every ICU patient','Routine thyroid hormone treatment for this pattern is not recommended.'),('Central hypothyroidism is excluded permanently','Persistent abnormalities after recovery or a pituitary context need evaluation.')],
 'Severe illness alters conversion, binding and central signaling', '**Low T3 is a common early change.**',['TSH may transiently rise during recovery.','Drugs such as glucocorticoids and dopamine can modify results.'], '**Treat the underlying illness and reassess when appropriate.**',['Do not discontinue necessary established thyroid replacement indiscriminately.','Investigate a genuine endocrine emergency when the clinical picture supports it.'],[['Acute illness','Can lower T3 and alter TSH'],['Routine response','Treat illness, not a number alone'],['Follow-up','Reassess persistent or suspicious findings']],[HT,NI],'clinical_scenario')
q('A patient taking oral estrogen has high total T4 but normal TSH and a reliable normal free T4. What is the likely explanation?', 'Increased thyroxine-binding globulin',[
 ('Overt hyperthyroidism is proven by total T4 alone','Binding changes can raise total hormone while free function remains normal.'),('Central hypothyroidism is established','The free hormone and feedback are normal.'),('All high total T4 requires an antithyroid drug','Treatment depends on true hormone excess.')],
 'Binding-protein changes alter total hormone concentrations', '**Estrogen increases TBG and the bound hormone pool.**',['A euthyroid person can compensate and maintain normal free hormone.','Patients on fixed levothyroxine may need reassessment after estrogen changes.'], '**Use appropriate free-hormone and TSH interpretation.**',['Pregnancy adds assay and reference-interval considerations.','Do not diagnose thyrotoxicosis from total T4 alone.'],[['TBG','Increased'],['Total T4','Can rise'],['Function','Can remain normal']],[HT,PG],'clinical_scenario')
q('Persistent TSH below 0.1 mIU/L accompanies normal free T4 and T3 in an older adult. What issue most strongly supports treatment assessment?', 'Risk of atrial fibrillation and skeletal harm from persistent subclinical hyperthyroidism',[
 ('Normal free hormones mean no possible clinical consequences','Persistent TSH suppression can carry risk.'),('The pattern is subclinical hypothyroidism','The TSH direction is opposite.'),('Every single low TSH during illness requires immediate definitive therapy','Persistence and the cause must be established.')],
 'Subclinical describes the laboratory pattern, not the absence of risk', '**Age, cardiovascular disease, osteoporosis and degree of TSH suppression affect treatment decisions.**',['Autonomy, Graves disease and excess replacement are different causes.','Transient illness and drugs can suppress TSH.'], '**Confirm persistence and identify the mechanism.**',['Avoid treating one confounded value.','Use cause-specific rather than universal therapy.'],[['Pattern','Low TSH/normal free hormones'],['Higher risk','Older age and cardiac/bone disease'],['Decision','Persistence plus etiology']],[TH,NI])
q('Free T4 is elevated repeatedly but TSH is not suppressed. What is the best first diagnostic principle?', 'Check assay interference, drugs and the clinical context before pursuing rare central causes',[
 ('The result automatically proves a TSH-secreting adenoma','Interference and binding issues are important alternatives.'),('The pattern is ordinary Graves disease','TSH is normally suppressed in primary thyrotoxicosis.'),('Thyroid hormone resistance and assay problems can be ignored','They are central differential considerations.')],
 'A feedback mismatch requires verification', '**Analytical artifacts can mimic inappropriate TSH secretion.**',['Thyroid hormone resistance and TSH-secreting tumors are true biological possibilities.','Family phenotype and additional biochemical data help distinguish them.'], '**Confirm the laboratory pattern before imaging-driven treatment.**',['Use another method or platform when appropriate.','Do not operate on an incidental pituitary lesion without establishing its function.'],[['First','Verify the assay and exposure context'],['True causes','Resistance or TSH-secreting tumor'],['Imaging','After biochemical clarification']],[TH,HT])
q('A woman on stable levothyroxine confirms pregnancy. What is the usual immediate planning principle?', 'Arrange prompt thyroid testing and an early increase in replacement according to the pre-agreed pregnancy plan',[
 ('Continue unchanged until delivery regardless of tests','Requirements commonly rise early in pregnancy.'),('Stop levothyroxine because thyroid hormone is teratogenic','Adequate replacement is important for maternal and fetal health.'),('Use the nonpregnant reference range without considering gestation','Pregnancy requires appropriate reference interpretation.')],
 'Replacement needs can rise before the first routine antenatal visit', '**The 2026 ATA guidance supports an early increase, commonly about 20–30%, in suitable patients with established hypothyroidism.**',['Individual requirements vary.','Monitor using pregnancy-appropriate tests and intervals.'], '**Review supplements and administration.**',['Iron and calcium can interfere with absorption.','Plan postpartum dose reassessment rather than leaving the pregnancy dose indefinitely.'],[['Early pregnancy','Higher replacement need is common'],['Action','Prompt dose and test plan'],['After delivery','Reassess requirements']],[PG],'clinical_scenario')
q('Several months postpartum, a woman develops mild thyrotoxicosis followed later by hypothyroidism. There is no orbitopathy and TRAb is negative. Which mechanism is likely?', 'Destructive postpartum thyroiditis',[
 ('New hormone synthesis from autonomous nodules is the characteristic sequence','The biphasic autoimmune postpartum course suggests thyroiditis.'),('Every postpartum thyrotoxicosis requires antithyroid drugs','Destructive hormone release does not respond to synthesis blockade in the same way.'),('A negative TRAb absolutely excludes every possible Graves case','It supports the differential but must be interpreted with the whole picture.')],
 'Stored hormone release differs from increased synthesis', '**Postpartum thyroiditis can have thyrotoxic and hypothyroid phases.**',['Not every patient experiences both phases.','Some develop persistent hypothyroidism.'], '**Use symptomatic therapy and phase-specific follow-up.**',['Beta blockade may help selected thyrotoxic symptoms.','Consider levothyroxine during clinically important hypothyroidism, especially with reproductive plans.'],[['Early mechanism','Destructive release'],['Later phase','Possible hypothyroidism'],['Antithyroid drugs','Not useful for simple destructive release']],[PG,TH],'clinical_scenario')
